(\forall ZA)[X:=Y]=
\begin{cases}
\forall ZA,&Z=X,\\
\forall Z(A[X:=Y]),&Z\ne X\land Z\ne Y,\\
\forall W((A[Z:=W])[X:=Y]),&Z\ne X\land Z=Y,
\end{cases}

